export function target(url) {
  const u = new URL(url);
  let path = u.pathname;
  if (path.length > 1 && path.endsWith("/")) path = path.replace(/\/+$/, "");
  const to = TABLE[path] ?? `${DOCS}/legacy${path}`;
  return to + u.search;
}

export default {
  fetch(request) {
    return Response.redirect(target(request.url), 301);
  },
};
